import { v4 as uuidv4 } from 'uuid';
import { AppStatus, Chunk, IndexState } from '../shared/types';
import { DocumentService } from './document-service';
import { PersistenceService } from './persistence-service';

const INDEX_META = 'index/index-meta.json';
const CHUNKS_DIR = 'chunks';
export const CHUNK_SIZE = 500;

/** Maps document IDs to the IDs of their chunks. */
type IndexMeta = Record<string, string[]>;

export class IndexingService {
  private persistence: PersistenceService;
  private documentService: DocumentService;
  private running = false;
  private lastError: string | null = null;
  private lastActivity = '';

  constructor(persistence: PersistenceService, documentService?: DocumentService) {
    this.persistence = persistence;
    this.documentService = documentService ?? new DocumentService(persistence);
  }

  /**
   * Index documents. With a documentId, (re)index just that document;
   * otherwise index every document that isn't in the index yet.
   */
  async startIndexing(documentId?: string): Promise<AppStatus> {
    this.running = true;
    this.lastError = null;
    try {
      const meta = this.readMeta();
      const targets = documentId
        ? [documentId]
        : this.documentService.listDocuments().filter(d => !meta[d.id]).map(d => d.id);

      for (const id of targets) {
        this.indexOne(id, meta);
      }
      this.persistence.writeJson(INDEX_META, meta);
    } catch (err) {
      this.lastError = err instanceof Error ? err.message : String(err);
    } finally {
      this.running = false;
      this.touch();
    }
    if (this.lastError) {
      throw new Error(this.lastError);
    }
    return this.getStatus();
  }

  /** Remove a document's chunks and index entry. */
  removeDocument(documentId: string): void {
    const meta = this.readMeta();
    delete meta[documentId];
    this.persistence.writeJson(INDEX_META, meta);
    this.persistence.deleteFile(`${CHUNKS_DIR}/${documentId}.json`);
    this.touch();
  }

  /** Current overall index status in the shape the status bar expects. */
  getStatus(): AppStatus {
    const docs = this.documentService.listDocuments();
    const meta = this.readMeta();
    const indexed = docs.filter(d => meta[d.id]).length;

    let indexStatus: IndexState;
    if (this.running) indexStatus = 'indexing';
    else if (this.lastError) indexStatus = 'error';
    else if (docs.length > 0 && indexed === docs.length) indexStatus = 'ready';
    else indexStatus = 'idle';

    return {
      documentsLoaded: docs.length,
      documentsIndexed: indexed,
      indexStatus,
      lastActivity: this.lastActivity,
    };
  }

  /** Get all chunks for a document. */
  getChunksForDocument(documentId: string): Chunk[] {
    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
  }

  /** Get all chunks across all indexed documents. */
  getAllChunks(): Chunk[] {
    const allChunks: Chunk[] = [];
    for (const docId of Object.keys(this.readMeta())) {
      allChunks.push(...this.getChunksForDocument(docId));
    }
    return allChunks;
  }

  private indexOne(documentId: string, meta: IndexMeta): void {
    const content = this.documentService.getDocumentContent(documentId);
    if (content === null) {
      throw new Error(`Document not found: ${documentId}`);
    }
    this.documentService.updateDocument(documentId, { status: 'indexing' });
    try {
      const chunks = chunkText(content).map((text, i) => createChunk(documentId, i, text));
      this.persistence.writeJson(`${CHUNKS_DIR}/${documentId}.json`, chunks);
      meta[documentId] = chunks.map(c => c.id);
      this.documentService.updateDocument(documentId, { status: 'indexed', chunks: chunks.length });
    } catch (err) {
      this.documentService.updateDocument(documentId, { status: 'error' });
      throw err;
    }
  }

  private readMeta(): IndexMeta {
    return this.persistence.readJson<IndexMeta>(INDEX_META) ?? {};
  }

  private touch(): void {
    this.lastActivity = new Date().toISOString();
  }
}

/**
 * Split text into ~CHUNK_SIZE-character chunks at paragraph boundaries.
 * Short paragraphs are merged; a single paragraph longer than CHUNK_SIZE is
 * split at sentence boundaries (or hard-wrapped if a sentence is itself huge).
 */
export function chunkText(content: string): string[] {
  const paragraphs = content
    .replace(/\r\n/g, '\n')
    .split(/\n\s*\n/)
    .map(p => p.trim())
    .filter(p => p.length > 0)
    .flatMap(splitOversized);

  const chunks: string[] = [];
  let buffer = '';
  for (const para of paragraphs) {
    if (buffer && buffer.length + 2 + para.length > CHUNK_SIZE) {
      chunks.push(buffer);
      buffer = para;
    } else {
      buffer = buffer ? `${buffer}\n\n${para}` : para;
    }
  }
  if (buffer) chunks.push(buffer);
  return chunks;
}

function splitOversized(paragraph: string): string[] {
  if (paragraph.length <= CHUNK_SIZE) return [paragraph];
  const sentences = paragraph.match(/[^.!?]+(?:[.!?]+|$)\s*/g) ?? [paragraph];
  const parts: string[] = [];
  let buffer = '';
  for (const raw of sentences) {
    for (let i = 0; i < raw.length; i += CHUNK_SIZE) {
      const piece = raw.slice(i, i + CHUNK_SIZE);
      if (buffer && buffer.length + piece.length > CHUNK_SIZE) {
        parts.push(buffer.trim());
        buffer = '';
      }
      buffer += piece;
    }
  }
  if (buffer.trim()) parts.push(buffer.trim());
  return parts;
}

function createChunk(documentId: string, index: number, content: string): Chunk {
  return {
    id: uuidv4(),
    documentId,
    content,
    index,
    metadata: {
      charCount: String(content.length),
      wordCount: String(content.split(/\s+/).filter(Boolean).length),
    },
  };
}

