  'most', 'other', 'over', 'each', 'used', 'using', 'your', 'yours', 'mine', 'within', 'between',
  'document', 'documents',
]);

/** Lowercase, split into words, drop stopwords, and apply light suffix stemming. */
export function tokenize(text: string): string[] {
  return (text.toLowerCase().match(/[a-z0-9]+/g) ?? [])
    .filter(w => w.length > 2 && !STOPWORDS.has(w))
    .map(stem);
}

function stem(word: string): string {
  if (word.length > 5 && word.endsWith('ies')) return `${word.slice(0, -3)}y`;
  if (word.length > 5 && word.endsWith('ing')) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith('ed')) return word.slice(0, -2);
  if (word.length > 3 && word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1);
  return word;
}

function splitSentences(text: string): string[] {
  return text
    .split(/\n+|(?<=[.!?])\s+/)
    .map(s => s.replace(/^\s*(#+|[-*]|\d+\.)\s+/, '').trim())
    .filter(s => s.length > 0);
}

export class QaService {
  private persistence: PersistenceService;
  private indexingService: IndexingService;
  private documentService: DocumentService;

  constructor(
    persistence: PersistenceService,
    indexingService?: IndexingService,
    documentService?: DocumentService,
  ) {
    this.persistence = persistence;
    this.documentService = documentService ?? new DocumentService(persistence);
    this.indexingService = indexingService ?? new IndexingService(persistence, this.documentService);
  }

  /** Answer a question from indexed chunks, citing the chunks the answer came from. */
  async ask(question: string): Promise<QAResponse> {
    if (typeof question !== 'string' || question.trim().length === 0) {
      throw new Error('Question must be a non-empty string');
    }
    const q = question.trim().slice(0, MAX_QUESTION_LENGTH);
    const queryTerms = [...new Set(tokenize(q))];
    const chunks = this.indexingService.getAllChunks();

    const ranked = this.rankChunks(chunks, queryTerms).slice(0, MAX_CITATIONS);
    const titles = new Map(this.documentService.listDocuments().map(d => [d.id, d.title]));
    const termSet = new Set(queryTerms);

    const citations: Citation[] = ranked.map(({ chunk }) => ({
      documentId: chunk.documentId,
      documentTitle: titles.get(chunk.documentId) ?? 'Unknown Document',
      chunkIndex: chunk.index,
      excerpt: bestExcerpt(chunk.content, termSet),
    }));

    let answer: string;
    if (chunks.length === 0) {
      answer = 'No documents have been indexed yet. Import and index documents, then ask again.';
    } else if (citations.length === 0) {
      answer = "I couldn't find anything in your indexed documents that matches this question. Try different keywords.";
    } else {
      answer = composeAnswer(ranked.map(r => r.chunk), citations, termSet);
    }

    const response: QAResponse = {
      answer,
      citations,
      confidence: citations.length > 0 ? CONFIDENCE_WITH_CITATIONS : CONFIDENCE_WITHOUT_CITATIONS,
      timestamp: new Date().toISOString(),
    };

    this.saveToHistory(q, response);
    return response;
  }

  /** Get the Q&A history, oldest first. */
  getHistory(): QAHistory[] {
    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
  }

  /** Score chunks by IDF-weighted overlap with the query terms. Highest first; zero scores dropped. */
  private rankChunks(chunks: Chunk[], queryTerms: string[]): Array<{ chunk: Chunk; score: number }> {
    if (queryTerms.length === 0 || chunks.length === 0) return [];
    const chunkTerms = chunks.map(c => new Set(tokenize(c.content)));

    const idf = new Map<string, number>();
    for (const term of queryTerms) {
      const df = chunkTerms.filter(set => set.has(term)).length;
      idf.set(term, df === 0 ? 0 : Math.log(1 + chunks.length / df));
    }

    return chunks
      .map((chunk, i) => ({
        chunk,
        score: queryTerms.reduce((acc, t) => acc + (chunkTerms[i].has(t) ? idf.get(t) ?? 0 : 0), 0),
      }))
      .filter(s => s.score > 0)
      .sort((a, b) => b.score - a.score || a.chunk.index - b.chunk.index);
  }

  private saveToHistory(question: string, response: QAResponse): void {
    const history = this.getHistory();
    history.push({ question, response });
