    this.persistence.writeJson(QA_HISTORY_FILE, history);
  }
}

function sentenceScore(sentence: string, terms: Set<string>): number {
  return new Set(tokenize(sentence).filter(t => terms.has(t))).size;
}

/** The highest-scoring sentence in the chunk, trimmed to the excerpt length. */
function bestExcerpt(content: string, terms: Set<string>): string {
  const sentences = splitSentences(content);
  let best = sentences[0] ?? content;
  let bestScore = -1;
  for (const s of sentences) {
    const score = sentenceScore(s, terms);
    if (score > bestScore) {
      best = s;
      bestScore = score;
    }
  }
  return best.length > EXCERPT_LENGTH ? `${best.slice(0, EXCERPT_LENGTH - 1).trimEnd()}…` : best;
}

/**
 * Build an extractive answer: the best-matching sentences from the cited
 * chunks, grouped by source document. Every sentence in the answer appears
 * verbatim in a cited chunk.
 */
function composeAnswer(chunks: Chunk[], citations: Citation[], terms: Set<string>): string {
  const candidates = chunks.flatMap((chunk, ci) =>
    splitSentences(chunk.content).map((text, si) => ({
      text,
      title: citations[ci].documentTitle,
      order: ci * 1000 + si,
      score: sentenceScore(text, terms),
    })),
  );

  const picked = candidates
    .filter(c => c.score > 0 && c.text.length > 15)
    .sort((a, b) => b.score - a.score || a.order - b.order)
    .slice(0, MAX_ANSWER_SENTENCES)
    .sort((a, b) => a.order - b.order);

  if (picked.length === 0) {
    return `The most relevant passage is from "${citations[0].documentTitle}": ${citations[0].excerpt}`;
  }

  const byTitle = new Map<string, string[]>();
  for (const p of picked) {
    const sentence = /[.!?:]$/.test(p.text) ? p.text : `${p.text}.`;
    byTitle.set(p.title, [...(byTitle.get(p.title) ?? []), sentence]);
  }
  return [...byTitle.entries()]
    .map(([title, sentences]) => `According to "${title}": ${sentences.join(' ')}`)
    .join('\n\n');
}

