import { BrowserWindow, dialog, IpcMain } from 'electron';
import * as fs from 'fs';
import { DocumentService } from '../services/document-service';
import { IndexingService } from '../services/indexing-service';
import { QaService } from '../services/qa-service';
import { Document, ImportResult, IPC_CHANNELS, SUPPORTED_EXTENSIONS } from '../shared/types';

export interface Services {
  documentService: DocumentService;
  indexingService: IndexingService;
  qaService: QaService;
}

export interface IpcOptions {
  /** Directory the import dialog opens in, if it exists. */
  importDefaultPath?: string;
}

function requireString(value: unknown, name: string): string {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error(`${name} must be a non-empty string`);
  }
  return value;
}

export function registerIpcHandlers(ipcMain: IpcMain, services: Services, options: IpcOptions = {}) {
  const { documentService, indexingService, qaService } = services;

  /** Import a file and index it immediately so it's searchable right away. */
  async function importAndIndex(filePath: string): Promise<Document> {
    const doc = documentService.importDocument(filePath);
    await indexingService.startIndexing(doc.id);
    return documentService.getDocument(doc.id) ?? doc;
  }

  // Document operations
  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, async () => {
    return documentService.listDocuments();
  });

  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENT, async (_event, filePath: unknown) => {
    return importAndIndex(requireString(filePath, 'filePath'));
  });

  ipcMain.handle(IPC_CHANNELS.PICK_AND_IMPORT, async (event): Promise<ImportResult> => {
    const win = BrowserWindow.fromWebContents(event.sender);
    const dialogOptions: Electron.OpenDialogOptions = {
      title: 'Import Documents',
      properties: ['openFile', 'multiSelections'],
      filters: [{ name: 'Text & Markdown', extensions: SUPPORTED_EXTENSIONS.map(e => e.slice(1)) }],
    };
    if (options.importDefaultPath && fs.existsSync(options.importDefaultPath)) {
      dialogOptions.defaultPath = options.importDefaultPath;
    }
    const result = win
      ? await dialog.showOpenDialog(win, dialogOptions)
      : await dialog.showOpenDialog(dialogOptions);

    const outcome: ImportResult = { imported: [], errors: [], canceled: result.canceled };
    for (const filePath of result.filePaths) {
      try {
        outcome.imported.push(await importAndIndex(filePath));
      } catch (err) {
        outcome.errors.push({ file: filePath, message: err instanceof Error ? err.message : String(err) });
      }
    }
    return outcome;
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, async (_event, id: unknown) => {
    return documentService.getDocument(requireString(id, 'id'));
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT_CONTENT, async (_event, id: unknown) => {
    return documentService.getDocumentContent(requireString(id, 'id'));
  });

  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, async (_event, id: unknown) => {
    const docId = requireString(id, 'id');
    indexingService.removeDocument(docId);
    return documentService.deleteDocument(docId);
  });

  // Indexing
  ipcMain.handle(IPC_CHANNELS.START_INDEXING, async (_event, documentId: unknown) => {
    return indexingService.startIndexing(
      documentId === undefined || documentId === null ? undefined : requireString(documentId, 'documentId'),
    );
  });

  ipcMain.handle(IPC_CHANNELS.GET_INDEXING_STATUS, async () => {
    return indexingService.getStatus();
  });

  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, async (_event, documentId: unknown) => {
    return indexingService.getChunksForDocument(requireString(documentId, 'documentId'));
  });

  // Q&A
  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: unknown) => {
    return qaService.ask(requireString(question, 'question'));
  });

  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, async () => {
    return qaService.getHistory();
  });

  // App status
  ipcMain.handle(IPC_CHANNELS.GET_STATUS, async () => {
    return indexingService.getStatus();
  });
}
