            onClick={() => onSelect(doc)}
            aria-current={selectedId === doc.id}
            title={doc.filename}
          >
            <div>{doc.title}</div>
            <div className="meta">
              <span className={`badge ${doc.status}`}>{doc.status}</span>{' '}
              {formatSize(doc.size)}
              {doc.chunks !== undefined && ` · ${doc.chunks} chunks`}
            </div>
          </button>
        </li>
      ))}
    </ul>
  );
}

