import { useEffect, useRef, useState } from 'react';
import type { Chunk, Document } from '../../shared/types';
import { formatSize } from './DocumentList';

interface Props {
  document: Document;
  /** Chunk to scroll to and highlight (e.g. from a clicked citation). */
  highlightChunk: number | null;
  onIndex: (doc: Document) => Promise<void>;
  onDelete: (doc: Document) => Promise<void>;
}

type Tab = 'content' | 'chunks';

export function DocumentDetail({ document, highlightChunk, onIndex, onDelete }: Props) {
  const [content, setContent] = useState<string | null>(null);
  const [chunks, setChunks] = useState<Chunk[]>([]);
  const [tab, setTab] = useState<Tab>('content');
  const [busy, setBusy] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const highlightRef = useRef<HTMLDivElement | null>(null);

  // Reload text and chunks whenever the document or its index state changes.
  useEffect(() => {
    let cancelled = false;
    setConfirmDelete(false);
    Promise.all([
      window.knowledgeBase.documents.content(document.id),
      window.knowledgeBase.indexing.chunks(document.id),
    ])
      .then(([text, docChunks]) => {
        if (cancelled) return;
        setContent(text);
        setChunks(docChunks);
      })
      .catch(err => console.error('Failed to load document:', err));
    return () => {
      cancelled = true;
    };
  }, [document.id, document.status, document.chunks]);

  useEffect(() => {
    if (highlightChunk !== null) setTab('chunks');
  }, [highlightChunk, document.id]);

  useEffect(() => {
    if (tab === 'chunks' && highlightChunk !== null) {
      highlightRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }, [tab, highlightChunk, chunks]);

  const run = async (action: () => Promise<void>) => {
    setBusy(true);
    try {
      await action();
    } finally {
      setBusy(false);
    }
  };

  return (
    <article>
      <h2 className="doc-title">{document.title}</h2>
      <div className="doc-meta">
        <span>{document.filename}</span>
        <span>{formatSize(document.size)}</span>
        <span>Imported {new Date(document.importedAt).toLocaleString()}</span>
        <span className={`badge ${document.status}`}>{document.status}</span>
        {document.chunks !== undefined && <span>{document.chunks} chunks</span>}
      </div>

      <div className="toolbar">
        <div className="tabs" role="tablist">
          <button role="tab" aria-selected={tab === 'content'} onClick={() => setTab('content')}>
            Content
          </button>
          <button role="tab" aria-selected={tab === 'chunks'} onClick={() => setTab('chunks')}>
            Chunks ({chunks.length})
          </button>
        </div>
        <button className="primary" disabled={busy} onClick={() => run(() => onIndex(document))}>
          {document.status === 'indexed' ? 'Re-index' : 'Index Document'}
        </button>
        {confirmDelete ? (
          <>
            <button className="danger" disabled={busy} onClick={() => run(() => onDelete(document))}>
              Confirm delete
            </button>
            <button disabled={busy} onClick={() => setConfirmDelete(false)}>Cancel</button>
          </>
        ) : (
          <button className="danger" disabled={busy} onClick={() => setConfirmDelete(true)}>
            Delete
          </button>
        )}
      </div>

      {tab === 'content' ? (
        <div className="doc-content">{content ?? 'Loading…'}</div>
      ) : chunks.length === 0 ? (
        <div className="empty">This document hasn't been indexed yet.</div>
      ) : (
        chunks.map(chunk => {
          const isHit = chunk.index === highlightChunk;
          return (
            <div
              key={chunk.id}
              ref={isHit ? highlightRef : undefined}
              className={`chunk${isHit ? ' highlight' : ''}`}
            >
              <div className="chunk-head">
                Chunk {chunk.index} · {chunk.metadata.charCount} chars · {chunk.metadata.wordCount} words
              </div>
              {chunk.content}
            </div>
          );
        })
      )}
    </article>
  );
}
