import { useCallback, useEffect, useState } from 'react';
import type { AppStatus, Citation, Document, QAHistory } from '../shared/types';
import { AnswerPanel } from './components/AnswerPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { DocumentList } from './components/DocumentList';
import { ImportPanel } from './components/ImportPanel';
import { QuestionPanel } from './components/QuestionPanel';
import { StatusBar } from './components/StatusBar';
import { errorMessage } from './lib/errors';

interface Notice {
  kind: 'error' | 'info';
  text: string;
}

const kb = () => window.knowledgeBase;

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [highlightChunk, setHighlightChunk] = useState<number | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    documentsIndexed: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [current, setCurrent] = useState<QAHistory | null>(null);
  const [asking, setAsking] = useState(false);
  const [notice, setNotice] = useState<Notice | null>(null);

  const selectedDoc = documents.find(d => d.id === selectedId) ?? null;

  const refresh = useCallback(async () => {
    try {
      const [docs, status] = await Promise.all([kb().documents.list(), kb().app.status()]);
      setDocuments(docs);
      setAppStatus(status);
    } catch (err) {
      setNotice({ kind: 'error', text: `Failed to load documents: ${errorMessage(err)}` });
    }
  }, []);

  useEffect(() => {
    refresh();
    kb()
      .qa.history()
      .then(h => setHistory(h))
      .catch(err => console.error('Failed to load Q&A history:', err));
  }, [refresh]);

  const reportImport = useCallback(
    async (imported: Document[], errors: Array<{ file: string; message: string }>) => {
      await refresh();
      if (imported.length > 0) setSelectedId(imported[imported.length - 1].id);
      if (errors.length > 0) {
        setNotice({
          kind: 'error',
          text: errors.map(e => `${e.file.split(/[\\/]/).pop()}: ${e.message}`).join(' · '),
        });
      } else if (imported.length > 0) {
        setNotice({ kind: 'info', text: `Imported and indexed ${imported.length} document(s).` });
      }
    },
    [refresh],
  );

  const handlePick = useCallback(async () => {
    try {
      const result = await kb().documents.pickAndImport();
      if (!result.canceled) await reportImport(result.imported, result.errors);
    } catch (err) {
      setNotice({ kind: 'error', text: `Import failed: ${errorMessage(err)}` });
    }
  }, [reportImport]);

  const handleDropPaths = useCallback(
    async (paths: string[]) => {
      const imported: Document[] = [];
      const errors: Array<{ file: string; message: string }> = [];
      for (const p of paths) {
        try {
          imported.push(await kb().documents.import(p));
        } catch (err) {
          errors.push({ file: p, message: errorMessage(err) });
        }
      }
      await reportImport(imported, errors);
    },
    [reportImport],
  );

  const handleSelect = useCallback((doc: Document) => {
    setSelectedId(doc.id);
    setHighlightChunk(null);
  }, []);

  const handleIndex = useCallback(
    async (doc?: Document) => {
      try {
        await kb().indexing.start(doc?.id);
      } catch (err) {
        setNotice({ kind: 'error', text: `Indexing failed: ${errorMessage(err)}` });
      }
      await refresh();
    },
    [refresh],
  );

  const handleDelete = useCallback(
    async (doc: Document) => {
      try {
        await kb().documents.delete(doc.id);
        setSelectedId(null);
        setNotice({ kind: 'info', text: `Deleted "${doc.title}".` });
      } catch (err) {
        setNotice({ kind: 'error', text: `Delete failed: ${errorMessage(err)}` });
      }
      await refresh();
    },
    [refresh],
  );

  const handleAsk = useCallback(
    async (question: string) => {
      setAsking(true);
      try {
        const response = await kb().qa.ask(question);
        const entry: QAHistory = { question, response };
        setHistory(h => [...h, entry]);
        setCurrent(entry);
      } catch (err) {
        setNotice({ kind: 'error', text: `Question failed: ${errorMessage(err)}` });
      } finally {
        setAsking(false);
      }
      refresh();
    },
    [refresh],
  );

  const handleCitation = useCallback(
    (c: Citation) => {
      if (!documents.some(d => d.id === c.documentId)) {
        setNotice({ kind: 'error', text: `"${c.documentTitle}" is no longer in the library.` });
        return;
      }
      setSelectedId(c.documentId);
      setHighlightChunk(c.chunkIndex);
    },
    [documents],
  );

  const unindexed = appStatus.documentsLoaded - appStatus.documentsIndexed;

  return (
    <>
      <header className="app-header">
        <h1>Knowledge Base</h1>
        <div style={{ display: 'flex', gap: 8 }}>
          {unindexed > 0 && (
            <button className="primary" onClick={() => handleIndex()}>
              Index all ({unindexed})
            </button>
          )}
          <button onClick={refresh}>Refresh</button>
        </div>
      </header>

      {notice && (
        <div className={`banner ${notice.kind}`} role={notice.kind === 'error' ? 'alert' : 'status'}>
          <span>{notice.text}</span>
          <button className="link" onClick={() => setNotice(null)} aria-label="Dismiss">
            ✕
          </button>
        </div>
      )}

      <div className="layout">
        <aside className="sidebar">
          <div className="sidebar-head">
            <span>Documents ({documents.length})</span>
            <button className="primary" onClick={handlePick}>
              + Import
            </button>
          </div>
          <DocumentList documents={documents} onSelect={handleSelect} selectedId={selectedId} />
        </aside>

        <main className="main">
          <div className="doc-pane">
            {selectedDoc ? (
              <DocumentDetail
                document={selectedDoc}
                highlightChunk={highlightChunk}
                onIndex={handleIndex}
                onDelete={handleDelete}
              />
            ) : (
              <div className="welcome">
                <h2>{documents.length === 0 ? 'Build your knowledge base' : 'Select a document'}</h2>
                <p>
                  {documents.length === 0
                    ? 'Import text or Markdown files, then ask questions below. Answers quote your documents and cite their sources.'
                    : 'Pick a document from the sidebar to read it, or ask a question below.'}
                </p>
                <ImportPanel onPick={handlePick} onDropPaths={handleDropPaths} />
              </div>
            )}
          </div>

          {current && (
            <div className="answer-pane">
              <AnswerPanel
                current={current}
                history={history}
                onCitation={handleCitation}
                onShowHistory={setCurrent}
              />
            </div>
          )}

          <QuestionPanel onAsk={handleAsk} busy={asking} />
        </main>
      </div>

      <StatusBar status={appStatus} />
    </>
  );
}

