      const [docs, status] = await Promise.all([kb().documents.list(), kb().app.status()]);
      setDocuments(docs);
      setAppStatus(status);
    } catch (err) {
      setNotice({ kind: 'error', text: `Failed to load documents: ${errorMessage(err)}` });
    }
  }, []);

  useEffect(() => {
    refresh();
    kb()
      .qa.history()
      .then(h => setHistory(h))
      .catch(err => console.error('Failed to load Q&A history:', err));
  }, [refresh]);

  const reportImport = useCallback(
    async (imported: Document[], errors: Array<{ file: string; message: string }>) => {
      await refresh();
      if (imported.length > 0) setSelectedId(imported[imported.length - 1].id);
      if (errors.length > 0) {
        setNotice({
          kind: 'error',
          text: errors.map(e => `${e.file.split(/[\\/]/).pop()}: ${e.message}`).join(' · '),
        });
      } else if (imported.length > 0) {
        setNotice({ kind: 'info', text: `Imported and indexed ${imported.length} document(s).` });
      }
    },
    [refresh],
  );

  const handlePick = useCallback(async () => {
    try {
      const result = await kb().documents.pickAndImport();
      if (!result.canceled) await reportImport(result.imported, result.errors);
    } catch (err) {
      setNotice({ kind: 'error', text: `Import failed: ${errorMessage(err)}` });
    }
  }, [reportImport]);

  const handleDropPaths = useCallback(
    async (paths: string[]) => {
      const imported: Document[] = [];
      const errors: Array<{ file: string; message: string }> = [];
      for (const p of paths) {
        try {
          imported.push(await kb().documents.import(p));
        } catch (err) {
          errors.push({ file: p, message: errorMessage(err) });
        }
      }
      await reportImport(imported, errors);
    },
    [reportImport],
  );

  const handleSelect = useCallback((doc: Document) => {
    setSelectedId(doc.id);
    setHighlightChunk(null);
  }, []);

  const handleIndex = useCallback(
    async (doc?: Document) => {
      try {
        await kb().indexing.start(doc?.id);
      } catch (err) {
        setNotice({ kind: 'error', text: `Indexing failed: ${errorMessage(err)}` });
      }
      await refresh();
    },
    [refresh],
  );

  const handleDelete = useCallback(
    async (doc: Document) => {
      try {
        await kb().documents.delete(doc.id);
        setSelectedId(null);
        setNotice({ kind: 'info', text: `Deleted "${doc.title}".` });
      } catch (err) {
        setNotice({ kind: 'error', text: `Delete failed: ${errorMessage(err)}` });
      }
      await refresh();
    },
    [refresh],
  );

  const handleAsk = useCallback(
    async (question: string) => {
      setAsking(true);
      try {
        const response = await kb().qa.ask(question);
        const entry: QAHistory = { question, response };
        setHistory(h => [...h, entry]);
        setCurrent(entry);
      } catch (err) {
        setNotice({ kind: 'error', text: `Question failed: ${errorMessage(err)}` });
      } finally {
        setAsking(false);
      }
      refresh();
    },
    [refresh],
  );

  const handleCitation = useCallback(
    (c: Citation) => {
      if (!documents.some(d => d.id === c.documentId)) {
        setNotice({ kind: 'error', text: `"${c.documentTitle}" is no longer in the library.` });
        return;
      }
      setSelectedId(c.documentId);
      setHighlightChunk(c.chunkIndex);
    },
    [documents],
