            </button>
          </div>
          <DocumentList documents={documents} onSelect={handleSelect} selectedId={selectedId} />
        </aside>

        <main className="main">
          <div className="doc-pane">
            {selectedDoc ? (
              <DocumentDetail
                document={selectedDoc}
                highlightChunk={highlightChunk}
                onIndex={handleIndex}
                onDelete={handleDelete}
              />
            ) : (
              <div className="welcome">
                <h2>{documents.length === 0 ? 'Build your knowledge base' : 'Select a document'}</h2>
                <p>
                  {documents.length === 0
                    ? 'Import text or Markdown files, then ask questions below. Answers quote your documents and cite their sources.'
                    : 'Pick a document from the sidebar to read it, or ask a question below.'}
                </p>
                <ImportPanel onPick={handlePick} onDropPaths={handleDropPaths} />
