                onCitation={handleCitation}
                onShowHistory={setCurrent}
              />
            </div>
          )}

          <QuestionPanel onAsk={handleAsk} busy={asking} />
        </main>
      </div>

      <StatusBar status={appStatus} />
    </>
  );
}

