/** Inverse document frequency over chunks: rarer terms count more. Unseen terms weigh 0. */
function idfWeights(chunks: Chunk[], queryTerms: string[]): Weigh {
  const chunkTerms = chunks.map(c => new Set(tokenize(c.content)));
  const idf = new Map<string, number>();
  for (const term of queryTerms) {
    const df = chunkTerms.filter(set => matches(set, term)).length;
    idf.set(term, df === 0 ? 0 : Math.log(1 + chunks.length / df));
  }
  return term => idf.get(term) ?? 0;
}

/** Score chunks by IDF-weighted query-term overlap. Highest first; zero scores dropped. */
function rankChunks(chunks: Chunk[], queryTerms: string[], weigh: Weigh): Array<{ chunk: Chunk; score: number }> {
  if (queryTerms.length === 0) return [];
  return chunks
    .map(chunk => {
      const tokens = new Set(tokenize(chunk.content));
      return { chunk, score: queryTerms.reduce((acc, t) => acc + (matches(tokens, t) ? weigh(t) : 0), 0) };
    })
    .filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score || a.chunk.index - b.chunk.index);
}
